def seed_categories(apps, schema_editor):
    """The five sections the forms used to hard-code, plus any other name
    already on an article, so no existing article loses its category."""
    Article = apps.get_model("editorial", "Article")
    Category = apps.get_model("editorial", "Category")
    used = Article.objects.exclude(category="").values_list("category", flat=True).distinct()
    seen = set()
